-- ═══════════════════════════════════════════════════
-- 2. INSERT program_modes (базовые: free_chat + author_chat)
-- Кастомные режимы — в seed-borba-za-vnimanie-modes.sql
-- ═══════════════════════════════════════════════════

INSERT INTO program_modes (program_id, mode_template_id, enabled, sort_order, access_type, color_class, welcome_mode_label, welcome_title, welcome_subtitle, welcome_ai_message, welcome_replies, config)
SELECT
  p.id,
  mt.id,
  true,
  CASE
    WHEN mt.key = 'free_chat'    THEN 90
    WHEN mt.key = 'author_chat'  THEN 100
    ELSE mt.default_sort_order
  END,
  CASE
    WHEN mt.key = 'free_chat' THEN 'free'
    ELSE 'paid'
  END,
  'accent',
  CASE
    WHEN mt.key = 'free_chat'    THEN 'Свободный чат'
    WHEN mt.key = 'author_chat'  THEN 'Разговор с автором'
  END,
  CASE
    WHEN mt.key = 'free_chat'    THEN 'Просто поговорить'
    WHEN mt.key = 'author_chat'  THEN 'Спросить Макса'
  END,
  CASE
    WHEN mt.key = 'free_chat'    THEN 'Любой вопрос по книге, методике, твоему пласту реальности'
    WHEN mt.key = 'author_chat'  THEN 'Система в стиле Максима Белоусова — прямо и без штампов'
  END,
  CASE
    WHEN mt.key = 'free_chat' THEN
      E'Сюда можно с любым вопросом по методике или с конкретной ситуацией из жизни.\n\nПринёс точку контекста, которая бесит? Разберём по 5 столбцам. Не понимаешь концепцию? Объясню через пример. Хочешь спросить про теорию комнат или эквалайзер — спрашивай.\n\nЧто ты получишь:\n• Разбор твоей ситуации по методике контекстов\n• Объяснение концепций книги на твоих примерах\n• Прямой стоицизм-фрейм без «давай попробуем понять чувства»'
    WHEN mt.key = 'author_chat' THEN
      E'Спроси Макса. Принеси конкретное — ситуацию, кейс, вопрос.\n\nКак это работает: Система отвечает в стиле Белоусова из тренинга — прямо, провокационно, с требованием конкретики. Без «дорогой коллега» и «зажги свой потенциал».\n\nЧто ты получишь:\n• Прямой разбор без лести\n• Кейсы из жизни автора в авторском голосе\n• Стоицизм-фрейм и «не уходи от ответа»'
  END,
  CASE
    WHEN mt.key = 'free_chat' THEN
      '[
        {"text":"Хочу разобрать одну точку моего контекста", "type":"normal"},
        {"text":"Объясни концепцию контекстов простыми словами", "type":"normal"},
        {"text":"У меня застряло — посмотри", "type":"normal"},
        {"text":"Мне сложно сформулировать", "type":"exit"}
      ]'::jsonb
    WHEN mt.key = 'author_chat' THEN
      '[
        {"text":"Расскажи про свой кризис 2020", "type":"normal"},
        {"text":"Как ты вышел на эту методику?", "type":"normal"},
        {"text":"У меня застряло вот в чём — посмотри", "type":"normal"},
        {"text":"Расскажи что-то важное", "type":"exit"}
      ]'::jsonb
  END,
  '{}'::jsonb
FROM programs p
CROSS JOIN mode_templates mt
WHERE p.slug = 'borba-za-vnimanie'
  AND mt.key IN ('free_chat', 'author_chat')
ON CONFLICT DO NOTHING;

